-- State transitions declared for User (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION users_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('active', 'suspended'), ('inactive', 'active'), ('inactive', 'suspended'), ('pending_verification', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: users.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS users_status_transition_check ON users;
CREATE TRIGGER users_status_transition_check
    BEFORE UPDATE OF "status" ON users
    FOR EACH ROW EXECUTE FUNCTION users_status_transition_check();
